// Factory job planner: deterministic dependency planning for a spec of jobs.
//
// Exports planJobs(spec), which validates the spec and returns
//   { order: [ID], ready: [ID], blocked: [{ id, causes: [ID] }] }
//
// CLI: node job-plan.js SPECFILE
//   Reads UTF-8 JSON, prints the plan JSON plus a newline on stdout, exit 0.
//   Any invalid argument, unreadable input, invalid JSON, or invalid graph
//   writes a message to stderr, writes nothing to stdout, and exits 2.
//
// Only Node.js builtins are used.

import { readFileSync } from 'node:fs';
import process from 'node:process';

const PENDING = 'pending';
const SUCCEEDED = 'succeeded';
const FAILED = 'failed';
const VALID_STATES = [PENDING, SUCCEEDED, FAILED];

// Lexicographic order over raw string values (JavaScript <, code units).
function compareIds(a, b) {
  if (a < b) return -1;
  if (a > b) return 1;
  return 0;
}

// Minimal binary min-heap with a comparator, replacing node:buffer's MinHeap
// (unstable on this Node version). Values are raw job IDs (unique strings),
// so comparator results are unambiguous.
class MinHeap {
  constructor(compare) {
    this.items = [];
    this.compare = compare;
  }
  get size() {
    return this.items.length;
  }
  push(item) {
    const items = this.items;
    items.push(item);
    let i = items.length - 1;
    while (i > 0) {
      const parent = (i - 1) >> 1;
      if (this.compare(items[i], items[parent]) < 0) {
        [items[i], items[parent]] = [items[parent], items[i]];
        i = parent;
      } else {
        break;
      }
    }
  }
  pop() {
    const items = this.items;
    const top = items[0];
    const last = items.pop();
    if (items.length > 0) {
      items[0] = last;
      let i = 0;
      const n = items.length;
      for (;;) {
        const l = 2 * i + 1;
        const r = l + 1;
        let smallest = i;
        if (l < n && this.compare(items[l], items[smallest]) < 0) smallest = l;
        if (r < n && this.compare(items[r], items[smallest]) < 0) smallest = r;
        if (smallest === i) break;
        [items[i], items[smallest]] = [items[smallest], items[i]];
        i = smallest;
      }
    }
    return top;
  }
}

// Kahn's algorithm over the entire graph. Repeatedly removes the lexically
// smallest currently zero-indegree ID (code-unit string order), and all
// remaining nodes are returned in removal order. Throws on a cycle or a
// duplicate node id.
function topologicalOrder(ids, depsOf) {
  const order = [];
  const indegree = new Map();
  const children = new Map();
  for (const id of ids) {
    if (indegree.has(id)) {
      throw new Error(`duplicate job id: ${JSON.stringify(id)}`);
    }
    indegree.set(id, 0);
    children.set(id, []);
  }
  for (const id of ids) {
    for (const dep of depsOf(id)) {
      if (!indegree.has(dep)) {
        throw new Error(`unknown dependency ${JSON.stringify(dep)} referenced by job ${JSON.stringify(id)}`);
      }
      indegree.set(id, indegree.get(id) + 1);
      children.get(dep).push(id);
    }
  }
  const ready = new MinHeap((a, b) => compareIds(a, b));
  for (const [id, deg] of indegree) {
    if (deg === 0) ready.push(id);
  }
  while (ready.size > 0) {
    const id = ready.pop();
    order.push(id);
    for (const child of children.get(id)) {
      const deg = indegree.get(child) - 1;
      indegree.set(child, deg);
      if (deg === 0) ready.push(child);
    }
  }
  if (order.length !== ids.length) {
    throw new Error('dependency cycle detected');
  }
  return order;
}

// All failed ancestors of every job, found by walking the reverse (dependents)
// graph in topological order, so a failed job propagates to every transitive
// dependent through any intermediate state. Returns a Map of id -> Set of
// failed-ancestor ids.
function failedAncestors(topoOrder, depsOf, stateOf) {
  const causes = new Map();
  for (const id of topoOrder) {
    let set = null;
    for (const dep of depsOf(id)) {
      if (stateOf(dep) === FAILED) {
        if (set === null) set = new Set();
        set.add(dep);
      }
      const depCauses = causes.get(dep);
      if (depCauses) {
        if (set === null) set = new Set();
        for (const c of depCauses) set.add(c);
      }
    }
    if (set) causes.set(id, set);
  }
  return causes;
}

export function planJobs(spec) {
  if (!Array.isArray(spec)) {
    throw new Error('spec must be an array of job objects');
  }

  // Validate shape without mutating or coercing the input. Duplicate IDs are
  // detected structurally, so __proto__ and constructor are ordinary IDs.
  const states = new Map();
  const depsById = new Map();
  for (const job of spec) {
    if (typeof job !== 'object' || job === null || Array.isArray(job)) {
      throw new Error('each job must be an object');
    }
    const { id, deps, state } = job;
    if (typeof id !== 'string' || id.length === 0) {
      throw new Error(`job id must be a nonempty string, got: ${JSON.stringify(id)}`);
    }
    if (depsById.has(id)) {
      throw new Error(`duplicate job id: ${JSON.stringify(id)}`);
    }
    if (typeof state !== 'string' || !VALID_STATES.includes(state)) {
      throw new Error(`job ${JSON.stringify(id)} has invalid state: ${JSON.stringify(state)}`);
    }
    if (!Array.isArray(deps)) {
      throw new Error(`job ${JSON.stringify(id)} deps must be an array`);
    }
    const seen = new Set();
    for (const dep of deps) {
      if (typeof dep !== 'string' || dep.length === 0) {
        throw new Error(`job ${JSON.stringify(id)} has a non-string or empty dependency`);
      }
      if (seen.has(dep)) {
        throw new Error(`duplicate dependency ${JSON.stringify(dep)} of job ${JSON.stringify(id)}`);
      }
      seen.add(dep);
    }
    states.set(id, state);
    depsById.set(id, deps);
  }

  // Deterministic topological ordering of the ENTIRE graph (Kahn's algorithm,
  // smallest zero-indegree id first). Throws on missing references or cycles,
  // including cycles among completed/failed jobs and self-dependencies.
  const topoOrder = topologicalOrder([...states.keys()], (id) => depsById.get(id));

  const causes = failedAncestors(topoOrder, (id) => depsById.get(id), (id) => states.get(id));

  const order = [];
  const ready = [];
  const blocked = [];
  for (const id of topoOrder) {
    if (states.get(id) !== PENDING) continue; // failed/succeeded jobs never appear
    const causeSet = causes.get(id);
    if (causeSet) {
      blocked.push({ id, causes: [...causeSet].sort(compareIds) });
    } else {
      order.push(id);
      if (depsById.get(id).every((dep) => states.get(dep) === SUCCEEDED)) {
        ready.push(id);
      }
    }
  }
  return { order, ready, blocked };
}

function runCli(argv) {
  if (argv.length !== 1) {
    process.stderr.write('usage: node job-plan.js SPECFILE\n');
    process.exit(2);
  }
  let raw;
  try {
    raw = readFileSync(argv[0], 'utf8');
  } catch (err) {
    process.stderr.write(`job-plan: cannot read ${argv[0]}: ${err.message}\n`);
    process.exit(2);
  }
  let spec;
  try {
    spec = JSON.parse(raw);
  } catch (err) {
    process.stderr.write(`job-plan: invalid JSON: ${err.message}\n`);
    process.exit(2);
  }
  let plan;
  try {
    plan = planJobs(spec);
  } catch (err) {
    process.stderr.write(`job-plan: invalid graph: ${err.message}\n`);
    process.exit(2);
  }
  process.stdout.write(`${JSON.stringify(plan)}\n`);
  process.exit(0);
}

if (import.meta.main) {
  runCli(process.argv.slice(2));
}

