import test from 'node:test';
import assert from 'node:assert/strict';
import { planJobs } from '../job-plan.js';
import { spawnSync } from 'node:child_process';
import { mkdtempSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const job = (id, deps = [], state = 'pending') => ({ id, deps, state });

test('topological order: smallest zero-indegree id first (Kahn, not waves, not input order)', () => {
  // All zero indegree, input order c,b,a => c,a? no: pick 'a' then 'b' then 'c'.
  assert.deepEqual(planJobs([job('c'), job('b'), job('a')]), {
    order: ['a', 'b', 'c'],
    ready: ['a', 'b', 'c'],
    blocked: [],
  });
  // Chain: a <- b <- c; only one zero-indegree node at each step.
  assert.deepEqual(planJobs([job('c', ['b']), job('b', ['a']), job('a')]), {
    order: ['a', 'b', 'c'],
    ready: ['a'],
    blocked: [],
  });
  // 'z' is available from the start but 'a' (smaller) is released by 'b'.
  assert.deepEqual(planJobs([job('z'), job('b'), job('a', ['b'])]), {
    order: ['b', 'a', 'z'],
    ready: ['b', 'z'],
    blocked: [],
  });
});

test('full-graph order: pending jobs are placed against succeeded/failed predecessors, not just the pending subgraph', () => {
  // A succeeded predecessor: 'done' precedes 'top' in the full order, so the
  // filtered order keeps 'top' after it.
  assert.deepEqual(
    planJobs([job('top', ['done']), job('done', [], 'succeeded'), job('z')]),
    { order: ['top', 'z'], ready: ['top', 'z'], blocked: [] },
  );
  // Distinguishing case: 'a' waits on succeeded 's' AND pending 'r'; 'b'
  // waits only on 'r'. Full-graph Kahn: r, b, s, a -> ['r','b','a']. A
  // pending-only Kahn would yield ['a','b', ...] (a ahead of b).
  assert.deepEqual(
    planJobs([job('a', ['s', 'r']), job('s', [], 'succeeded'), job('r'), job('b', ['r'])]),
    { order: ['r', 'b', 'a'], ready: ['r'], blocked: [] },
  );
  // A blocked pending job is excluded from order/ready; its slot in the full
  // order is taken by the failed predecessor and the ready 'side' job.
  assert.deepEqual(
    planJobs([job('after', ['bad']), job('bad', [], 'failed'), job('side')]),
    { order: ['side'], ready: ['side'], blocked: [{ id: 'after', causes: ['bad'] }] },
  );
});

test('blocked: all failed ancestors, through any intermediate state, sorted uniquely', () => {
  assert.deepEqual(
    planJobs([
      job('end', ['mid1', 'mid2']),
      job('mid1', ['f2'], 'succeeded'), // succeeded intermediate does not erase ancestry
      job('mid2', ['f1'], 'failed'), // failed intermediate does not erase ancestry
      job('f1', [], 'failed'),
      job('f2', [], 'failed'),
    ]),
    {
      order: [],
      ready: [],
      blocked: [
        { id: 'end', causes: ['f1', 'f2'] },
        { id: 'mid2', causes: ['f1'] },
      ],
    },
  );
});

test('ready: unblocked pending whose direct deps are all succeeded; no-dep pending is ready', () => {
  assert.deepEqual(
    planJobs([
      job('go', ['ok']),
      job('ok', [], 'succeeded'),
      job('solo'),
      job('wait', ['ok', 'pending2']),
      job('pending2'),
    ]),
    { order: ['go', 'pending2', 'solo', 'wait'], ready: ['go', 'pending2', 'solo'], blocked: [] },
  );
});

test('self-dependency is a cycle', () => {
  assert.throws(() => planJobs([job('a', ['a'])]));
  assert.throws(() => planJobs([job('a', ['a'], 'succeeded')]));
});

test('cycles among completed/failed jobs are detected (whole graph)', () => {
  assert.throws(() => planJobs([job('a', ['b'], 'succeeded'), job('b', ['a'], 'succeeded')]));
  assert.throws(() => planJobs([job('a', ['b'], 'failed'), job('b', ['a'], 'failed')]));
});

test('malformed inputs throw', () => {
  assert.throws(() => planJobs('nope'));
  assert.throws(() => planJobs(null));
  assert.throws(() => planJobs([42]));
  assert.throws(() => planJobs([null]));
  assert.throws(() => planJobs([{ id: '', deps: [], state: 'pending' }]));
  assert.throws(() => planJobs([{ id: 'a', deps: [], state: 'running' }]));
  assert.throws(() => planJobs([{ id: 'a', deps: [], state: 1 }]));
  assert.throws(() => planJobs([{ id: 'a', state: 'pending' }])); // deps missing
  assert.throws(() => planJobs([{ id: 'a', deps: 'b' }])); // id missing, deps not array
  assert.throws(() => planJobs([job('a'), job('a')])); // duplicate IDs
  assert.throws(() => planJobs([job('a', ['b'])])); // missing reference
  assert.throws(() => planJobs([job('a', ['a', 'a'])])); // duplicate dependency
  assert.throws(() => planJobs([job('a', [''])])); // empty dependency id
  assert.throws(() => planJobs([job('a', [1])])); // non-string dependency
  // Non-string id is malformed, not coerced.
  assert.throws(() => planJobs([{ id: 1, deps: [], state: 'pending' }]));
});

test('__proto__ and constructor are ordinary IDs; input is not mutated', () => {
  const spec = [
    job('constructor', ['__proto__'], 'failed'),
    job('__proto__'),
    job('use', ['constructor']),
  ];
  const result = planJobs(spec);
  assert.deepEqual(result, {
    order: ['__proto__'],
    ready: ['__proto__'],
    blocked: [{ id: 'use', causes: ['constructor'] }],
  });
  assert.equal(spec[0].deps, ['__proto__']);
  assert.equal(spec[0].id, 'constructor');
  assert.deepEqual(Object.keys(result), ['order', 'ready', 'blocked']);
});

test('unknown object fields are ignored; whitespace/Unicode ids preserved', () => {
  const result = planJobs([
    { id: '  spaced ', deps: [], state: 'pending', extra: 1, name: 'x' },
    { id: 'é', deps: ['  spaced '], state: 'pending' },
  ]);
  assert.deepEqual(result, {
    order: ['  spaced ', 'é'],
    ready: ['  spaced '],
    blocked: [],
  });
});

test('empty spec is valid', () => {
  assert.deepEqual(planJobs([]), { order: [], ready: [], blocked: [] });
});

test('large chain and diamond do not blow the call stack', () => {
  const n = 50000;
  const spec = [job('j0')];
  for (let i = 1; i < n; i++) spec.push(job(`j${i}`, [`j${i - 1}`]));
  const result = planJobs(spec);
  assert.equal(result.order.length, n);
  assert.equal(result.order[0], 'j0');
  assert.deepEqual(result.blocked, []);
  assert.deepEqual(result.ready, ['j0']);
});

// ---- CLI behaviour ----

const SCRIPT = join(dirname(fileURLToPath(import.meta.url)), '..', 'job-plan.js');

function runCli(args) {
  return spawnSync(process.execPath, [SCRIPT, ...args], { encoding: 'utf8' });
}

test('cli: valid spec prints JSON + newline, exit 0, no stderr', () => {
  const dir = mkdtempSync(join(tmpdir(), 'job-plan-'));
  const file = join(dir, 'spec.json');
  writeFileSync(file, JSON.stringify([job('b', ['a']), job('a')]), 'utf8');
  try {
    const r = runCli([file]);
    assert.equal(r.status, 0);
    assert.equal(r.stderr, '');
    assert.equal(r.stdout, `${JSON.stringify({ order: ['a', 'b'], ready: ['a'], blocked: [] })}\n`);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

test('cli: wrong argument count exits 2 with stderr and no stdout', () => {
  for (const args of [[], ['a', 'b']]) {
    const r = runCli(args);
    assert.equal(r.status, 2);
    assert.equal(r.stdout, '');
    assert.ok(r.stderr.length > 0);
  }
});

test('cli: unreadable file exits 2 with stderr and no stdout', () => {
  const r = runCli(['/definitely/missing/nope.json']);
  assert.equal(r.status, 2);
  assert.equal(r.stdout, '');
  assert.ok(r.stderr.length > 0);
});

test('cli: invalid JSON and invalid graph exit 2 with stderr and no stdout', () => {
  const dir = mkdtempSync(join(tmpdir(), 'job-plan-'));
  const badJson = join(dir, 'bad.json');
  const badGraph = join(dir, 'cycle.json');
  writeFileSync(badJson, '{ nope', 'utf8');
  writeFileSync(badGraph, JSON.stringify([job('a', ['b']), job('b', ['a'])]), 'utf8');
  writeFileSync(join(dir, 'notarray.json'), JSON.stringify({ a: 1 }), 'utf8');
  try {
    for (const file of [badJson, badGraph, join(dir, 'notarray.json')]) {
      const r = runCli([file]);
      assert.equal(r.status, 2, file);
      assert.equal(r.stdout, '', file);
      assert.ok(r.stderr.length > 0, file);
    }
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

test('importing the module does not run the CLI', () => {
  // planJobs is imported above; also confirm the module side-effect guard by
  // running the file with no args through node -e import (exit 0, no output).
  const r = spawnSync(
    process.execPath,
    ['-e', `await import(${JSON.stringify(SCRIPT)});`],
    { encoding: 'utf8' },
  );
  assert.equal(r.status, 0);
  assert.equal(r.stdout, '');
  assert.equal(r.stderr, '');
});

